/**
 * Hydrates <seam-island> elements. Loaded only when a page has at least one island,
 * so pages without islands never download React.
 */
import { createElement, type ComponentType } from "react";
import { hydrateRoot, type Root } from "react-dom/client";
// Generated by the Vite plugin from .seam/islands.gen.ts
import { islands } from "virtual:seam/islands";

interface Mounted {
  root: Root;
  Component: ComponentType<any>;
  props: string;
}

const mounted = new WeakMap<Element, Mounted>();

export function hydrateIslands(scope: ParentNode = document): void {
  for (const el of scope.querySelectorAll<HTMLElement>("seam-island:not([data-seam-started])")) {
    el.setAttribute("data-seam-started", "");
    const when = el.dataset.hydrate ?? "load";
    if (when === "idle") {
      const ric = (window as any).requestIdleCallback ?? ((cb: () => void) => setTimeout(cb, 200));
      ric(() => hydrateOne(el));
    } else if (when === "visible") {
      const io = new IntersectionObserver((entries) => {
        if (entries.some((e) => e.isIntersecting)) {
          io.disconnect();
          hydrateOne(el);
        }
      });
      io.observe(el);
    } else {
      hydrateOne(el);
    }
  }
}

async function hydrateOne(el: HTMLElement): Promise<void> {
  const id = el.dataset.island!;
  const load = islands[id];
  if (!load) {
    console.error(`[seam] unknown island ${id}`);
    return;
  }
  const mod = (await load()) as Record<string, unknown>;
  const Component = mod[el.dataset.export!] as ComponentType<any>;
  const props = el.dataset.props ?? "{}";
  const formState = el.dataset.formState ? JSON.parse(el.dataset.formState) : undefined;
  // RSC views the server already rendered into this island: <RscView> hydrates from them without fetching.
  if (el.dataset.rsc) {
    const preload = ((globalThis as any).__seamRscPreload ??= new Map<string, string>()) as Map<string, string>;
    for (const [src, flight] of Object.entries(JSON.parse(el.dataset.rsc) as Record<string, string>)) preload.set(src, flight);
  }
  const root = hydrateRoot(el, createElement(Component, JSON.parse(props)), {
    identifierPrefix: el.dataset.prefix,
    formState,
  });
  el.setAttribute("data-hydrated", "");
  mounted.set(el, { root, Component, props });
}

/** Unmount islands inside `scope` that are not being kept. */
export function unmountIslands(scope: ParentNode, keep: Set<Element>): void {
  for (const el of scope.querySelectorAll("seam-island")) {
    if (keep.has(el)) continue;
    mounted.get(el)?.root.unmount();
    mounted.delete(el);
  }
}

/** A kept island got new props in the new HTML: re-render it, like a normal React prop change. */
export function updateIslandProps(el: HTMLElement, props: string | undefined): void {
  const m = mounted.get(el);
  if (!m || props === undefined || props === m.props) return;
  m.props = props;
  el.dataset.props = props;
  m.root.render(createElement(m.Component, JSON.parse(props)));
}
